"""Referee's closure (k <= 2 certificates) and independent exact checker."""
import math
from fractions import Fraction
from rcore import gmul, conj, Ds

FREE, HALF, EXACT = 0, 1, 2

class Quot:
    """Z^r / Pi with Pi generated by weight<=2 vectors: signed components, root status."""
    def __init__(self, r):
        self.par = list(range(r)); self.sg = [1] * r; self.st = [FREE] * r; self.size = [1] * r
    def find(self, k):
        path = []
        while self.par[k] != k:
            path.append(k); k = self.par[k]
        root = k
        # path compression with sign accumulation (process from top)
        for node in reversed(path):
            p = self.par[node]
            if p != root:
                self.sg[node] *= self.sg[p]
                self.par[node] = root
        return root
    def cls(self, v):
        """class of v: dict root -> coef, reduced by status."""
        c = {}
        for col, co in v:
            R = self.find(col); c[R] = c.get(R, 0) + co * self.sg[col]
        out = {}
        for R, co in c.items():
            st = self.st[R]
            if st == EXACT: continue
            if st == HALF: co %= 2
            if co: out[R] = co
        return out
    def add(self, v):
        c = self.cls(v)
        if not c: return False
        items = list(c.items())
        if len(items) == 1:
            R, co = items[0]
            if self.st[R] == HALF or abs(co) == 1: self.st[R] = EXACT
            else:
                assert abs(co) == 2; self.st[R] = HALF
            return True
        assert len(items) == 2
        (R1, c1), (R2, c2) = items
        assert abs(c1) == 1 and abs(c2) == 1, (c1, c2)
        # relation c1 e_R1 + c2 e_R2 = 0  ->  e_R2 = -c1 c2 e_R1 (in Z/2 parts sign is irrelevant)
        if self.size[R1] < self.size[R2]: R1, R2, c1, c2 = R2, R1, c2, c1
        s = -c1 * c2
        st1, st2 = self.st[R1], self.st[R2]
        self.par[R2] = R1; self.sg[R2] = s; self.size[R1] += self.size[R2]
        if EXACT in (st1, st2): new = EXACT
        elif HALF in (st1, st2): new = HALF
        else: new = FREE
        self.st[R1] = new
        return True

def representable(key):
    """class reachable by Quot.add: <= 2 roots, coefficients +-1 (or one root +-2)."""
    if len(key) == 1: return abs(key[0][1]) in (1, 2)
    return len(key) == 2 and all(abs(co) == 1 for R, co in key)

def key_of(c):
    """normalised class key, orientation factor eps, and whether the class is oriented."""
    items = sorted(c.items())
    zparts = [co for R, co in items if True]
    return items

def closure(r, rels, quot=None):
    """rels: list of (v, s, sigma, sin2d). Returns (Quot, certificate log).
    log entries: list of (rel_index, n) and the vectors added."""
    Q = quot or Quot(r); log = []
    changed = True
    while changed:
        changed = False
        buckets = {}
        for idx, (v, s, sig, s2) in enumerate(rels):
            c = Q.cls(v)
            if not c: continue
            items = sorted(c.items())
            zco = [co for R, co in items if Q.st[R] == FREE]
            if zco:
                eps = 1 if zco[0] > 0 else -1
                key = tuple((R, co * eps if Q.st[R] == FREE else co) for R, co in items)
                o = sig * eps
            else:
                key = tuple(items); o = 0
            b = buckets.setdefault(key, {1: None, -1: None, 0: None})
            cur = b[o]
            if cur is None or rels[cur][3] < s2: b[o] = idx
        for key, b in buckets.items():
            if not representable(key): continue
            if b[0] is not None:
                i = b[0]
                if rels[i][3] > Fraction(1, 2):
                    log.append(([(i, 2)], [rels[i][0]]))
                    Q.add(rels[i][0]); changed = True
            else:
                i, j = b[1], b[-1]
                if i is not None and j is not None and rels[i][3] + rels[j][3] > 1:
                    log.append(([(i, 1), (j, 1)], [rels[i][0], rels[j][0]]))
                    Q.add(rels[i][0]); Q.add(rels[j][0]); changed = True
    return Q, log

def status(Q, r):
    out = []
    for k in range(r):
        R = Q.find(k); out.append(Q.st[R])
    return out

# ---------------- independent checker ----------------
class Lattice:
    """sparse echelon basis over Z; rows keyed by leading column, leading entry > 0."""
    def __init__(self): self.piv = {}
    def _reduce(self, vec, insert):
        vec = {k: x for k, x in vec.items() if x}
        while vec:
            c = min(vec); a = vec[c]
            P = self.piv.get(c)
            if P is None:
                if insert:
                    if a < 0: vec = {k: -x for k, x in vec.items()}
                    self.piv[c] = vec
                    return True
                return False
            p = P[c]
            if a % p == 0:
                f = a // p
                for k, x in P.items():
                    y = vec.get(k, 0) - f * x
                    if y: vec[k] = y
                    else: vec.pop(k, None)
                continue
            if not insert: return False
            g = math.gcd(a, p); x0, y0 = _egcd(p, a)  # x0 p + y0 a = g
            newP = {}
            for k in set(P) | set(vec):
                val = x0 * P.get(k, 0) + y0 * vec.get(k, 0)
                if val: newP[k] = val
            newV = {}
            for k in set(P) | set(vec):
                val = (p // g) * vec.get(k, 0) - (a // g) * P.get(k, 0)
                if val: newV[k] = val
            self.piv[c] = newP; vec = newV
        return True
    def member(self, vec): return self._reduce(dict(vec), False) or not any(vec.values())
    def insert(self, vec): self._reduce(dict(vec), True)

def _egcd(a, b):
    x0, y0, x1, y1 = 1, 0, 0, 1
    while b:
        q = a // b; a, b = b, a - q * b; x0, x1 = x1, x0 - q * x1; y0, y1 = y1, y0 - q * y1
    if a < 0: a, x0, y0 = -a, -x0, -y0
    return x0, y0

def A_of(gp, v):
    A = (1, 0)
    for col, co in v:
        z = gp[col] if co > 0 else conj(gp[col])
        for _ in range(abs(co)): A = gmul(A, z)
    return A

def check(gp, L, rels, log):
    """re-verify every certificate from scratch; return (#certs ok, list of exactly/half pinned)."""
    r = len(gp); lat = Lattice(); ok = 0
    for terms, added in log:
        u = {}
        arc = Fraction(0)  # sum n_i (1 - 2 d_i/pi) < 1  <=>  checked via sin^2 below
        s2s = []
        for idx, n in terms:
            v, s, _, _ = rels[idx]
            A = A_of(gp, v)
            D = Ds(A)[s]
            assert D != 0 and L % abs(D) == 0, 'not tight'
            # orientation from Im(A^2 * (-i)^s), independent of Lemma 2.3(2)
            B = gmul(A, A)
            for _ in range(s): B = gmul(B, (0, -1))
            sig = (B[1] > 0) - (B[1] < 0)
            # sin^2 d from Im(A (1-i)^s)^2 / (2^s |A|^2)
            Cz = A
            for _ in range(s): Cz = gmul(Cz, (1, -1))
            s2 = Fraction(Cz[1] ** 2, 2 ** s * (A[0] ** 2 + A[1] ** 2))
            s2s.append((n, s2))
            for col, co in v: u[col] = u.get(col, 0) + n * sig * co
        if len(s2s) == 1:
            assert s2s[0][0] == 2 and s2s[0][1] > Fraction(1, 2)
        else:
            assert all(n == 1 for n, _ in s2s) and s2s[0][1] + s2s[1][1] > 1
        assert lat.member(u), 'circuit vector not in lattice'
        for v in added: lat.insert(dict(v))
        ok += 1
    exact = [k for k in range(r) if lat.member({k: 1})]
    half = [k for k in range(r) if lat.member({k: 2})]
    return ok, exact, half
